use std::fs;

use vcad::{centered_cube, centered_cylinder, Part};

// Closed humidity/dewpoint reference calibration station for incubator and cabinet modules.
//
// Stable STL outputs generated by this binary:
// - output/closed_humidity_dewpoint_reference_calibration_station_base_tray.stl
// - output/closed_humidity_dewpoint_reference_calibration_station_probe_nest_plate.stl
// - output/closed_humidity_dewpoint_reference_calibration_station_reference_capsule_well_block.stl
// - output/closed_humidity_dewpoint_reference_calibration_station_condensation_catch_tray.stl
// - output/closed_humidity_dewpoint_reference_calibration_station_temperature_logger_pocket.stl
// - output/closed_humidity_dewpoint_reference_calibration_station_airflow_shield.stl
// - output/closed_humidity_dewpoint_reference_calibration_station_barcode_certificate_lands.stl
// - output/closed_humidity_dewpoint_reference_calibration_station_release_hold_reject_lanes.stl
// - output/closed_humidity_dewpoint_reference_calibration_station_service_bulkhead.stl
// - output/closed_humidity_dewpoint_reference_calibration_station_robot_keepout_gauge.stl
// - output/closed_humidity_dewpoint_reference_calibration_station_assembly.stl
//
// This is fixture/interface CAD only. Salt standards, chilled-mirror dewpoint
// references, logger calibration intervals, acceptance limits, and certificate
// release decisions remain validation-system controls outside this model.

const OUTPUTS: [&str; 11] = [
    "output/closed_humidity_dewpoint_reference_calibration_station_base_tray.stl",
    "output/closed_humidity_dewpoint_reference_calibration_station_probe_nest_plate.stl",
    "output/closed_humidity_dewpoint_reference_calibration_station_reference_capsule_well_block.stl",
    "output/closed_humidity_dewpoint_reference_calibration_station_condensation_catch_tray.stl",
    "output/closed_humidity_dewpoint_reference_calibration_station_temperature_logger_pocket.stl",
    "output/closed_humidity_dewpoint_reference_calibration_station_airflow_shield.stl",
    "output/closed_humidity_dewpoint_reference_calibration_station_barcode_certificate_lands.stl",
    "output/closed_humidity_dewpoint_reference_calibration_station_release_hold_reject_lanes.stl",
    "output/closed_humidity_dewpoint_reference_calibration_station_service_bulkhead.stl",
    "output/closed_humidity_dewpoint_reference_calibration_station_robot_keepout_gauge.stl",
    "output/closed_humidity_dewpoint_reference_calibration_station_assembly.stl",
];

const REQUIRED_FEATURES: [&str; 10] = [
    "rh_dewpoint_probe_nests",
    "sealed_salt_solution_reference_capsule_wells",
    "condensation_catch_tray",
    "temperature_logger_pocket",
    "airflow_shield",
    "barcode_certificate_lands",
    "release_hold_reject_lanes",
    "robot_keepouts",
    "service_bulkhead",
    "named_stl_exports",
];

const STATION_X: f64 = 940.0;
const STATION_Y: f64 = 640.0;
const BASE_Z: f64 = 22.0;
const RIM_W: f64 = 18.0;
const RIM_Z: f64 = 38.0;
const SOCKET_DEPTH: f64 = 5.0;
const MOUNT_SLOT_COUNT: usize = 6;
const DATUM_TARGET_COUNT: usize = 4;

const PROBE_NEST_X: f64 = 360.0;
const PROBE_NEST_Y: f64 = 124.0;
const PROBE_NEST_Z: f64 = 36.0;
const PROBE_NEST_COUNT: usize = 4;
const PROBE_NEST_PITCH_X: f64 = 76.0;
const PROBE_POS: (f64, f64) = (-245.0, 190.0);

const CAPSULE_BLOCK_X: f64 = 344.0;
const CAPSULE_BLOCK_Y: f64 = 154.0;
const CAPSULE_BLOCK_Z: f64 = 48.0;
const CAPSULE_WELL_COUNT: usize = 8;
const CAPSULE_WELL_PITCH_X: f64 = 74.0;
const CAPSULE_WELL_PITCH_Y: f64 = 58.0;
const CAPSULE_WELL_D: f64 = 36.0;
const CAPSULE_WELL_DEPTH: f64 = 31.0;
const CAPSULE_POS: (f64, f64) = (170.0, 190.0);

const CATCH_TRAY_X: f64 = 520.0;
const CATCH_TRAY_Y: f64 = 150.0;
const CATCH_TRAY_Z: f64 = 32.0;
const CATCH_BASIN_DEPTH: f64 = 18.0;
const CATCH_CHANNEL_COUNT: usize = 5;
const CATCH_POS: (f64, f64) = (-140.0, 35.0);

const LOGGER_BLOCK_X: f64 = 230.0;
const LOGGER_BLOCK_Y: f64 = 112.0;
const LOGGER_BLOCK_Z: f64 = 42.0;
const LOGGER_POCKET_COUNT: usize = 2;
const LOGGER_POS: (f64, f64) = (300.0, 35.0);

const AIRFLOW_SHIELD_X: f64 = 690.0;
const AIRFLOW_SHIELD_Y: f64 = 92.0;
const AIRFLOW_SHIELD_Z: f64 = 116.0;
const AIRFLOW_WINDOW_COUNT: usize = 9;
const AIRFLOW_POS: (f64, f64) = (-30.0, -85.0);

const TRACE_PLATE_X: f64 = 286.0;
const TRACE_PLATE_Y: f64 = 94.0;
const TRACE_PLATE_Z: f64 = 10.0;
const BARCODE_LAND_COUNT: usize = 6;
const CERTIFICATE_LAND_COUNT: usize = 2;
const TRACE_POS: (f64, f64) = (300.0, -220.0);

const LANE_PLATE_X: f64 = 520.0;
const LANE_PLATE_Y: f64 = 120.0;
const LANE_PLATE_Z: f64 = 18.0;
const LANE_COUNT: usize = 3;
const LANE_POS: (f64, f64) = (-145.0, -220.0);

const BULKHEAD_X: f64 = 780.0;
const BULKHEAD_Y: f64 = 34.0;
const BULKHEAD_Z: f64 = 110.0;
const BULKHEAD_PORT_COUNT: usize = 8;
const BULKHEAD_POS: (f64, f64) = (0.0, 258.0);

const KEEP_OUT_X: f64 = 872.0;
const KEEP_OUT_Y: f64 = 580.0;
const KEEP_OUT_Z: f64 = 5.0;
const ROBOT_KEEP_OUT_ZONE_COUNT: usize = 4;

const FRONT_ROBOT_APPROACH_CLEARANCE: f64 = 36.0;
const SERVICE_SWEEP_CLEARANCE: f64 = 42.0;

fn main() {
    fs::create_dir_all("output").unwrap();
    assert_design_constraints();

    let base = base_tray();
    export(&base, OUTPUTS[0]);

    let probe_nests = probe_nest_plate();
    export(&probe_nests, OUTPUTS[1]);

    let capsules = reference_capsule_well_block();
    export(&capsules, OUTPUTS[2]);

    let catch_tray = condensation_catch_tray();
    export(&catch_tray, OUTPUTS[3]);

    let logger = temperature_logger_pocket();
    export(&logger, OUTPUTS[4]);

    let airflow = airflow_shield();
    export(&airflow, OUTPUTS[5]);

    let traceability = barcode_certificate_lands();
    export(&traceability, OUTPUTS[6]);

    let lanes = release_hold_reject_lanes();
    export(&lanes, OUTPUTS[7]);

    let bulkhead = service_bulkhead();
    export(&bulkhead, OUTPUTS[8]);

    let keepouts = robot_keepout_gauge();
    export(&keepouts, OUTPUTS[9]);

    let assembly = base
        + probe_nests.translate(PROBE_POS.0, PROBE_POS.1, on_base_z(PROBE_NEST_Z))
        + capsules.translate(CAPSULE_POS.0, CAPSULE_POS.1, on_base_z(CAPSULE_BLOCK_Z))
        + catch_tray.translate(CATCH_POS.0, CATCH_POS.1, on_base_z(CATCH_TRAY_Z))
        + logger.translate(LOGGER_POS.0, LOGGER_POS.1, on_base_z(LOGGER_BLOCK_Z))
        + airflow.translate(AIRFLOW_POS.0, AIRFLOW_POS.1, on_base_z(AIRFLOW_SHIELD_Z))
        + traceability.translate(TRACE_POS.0, TRACE_POS.1, on_base_z(TRACE_PLATE_Z))
        + lanes.translate(LANE_POS.0, LANE_POS.1, on_base_z(LANE_PLATE_Z))
        + bulkhead.translate(BULKHEAD_POS.0, BULKHEAD_POS.1, on_base_z(BULKHEAD_Z))
        + keepouts.translate(0.0, 0.0, BASE_Z / 2.0 + KEEP_OUT_Z / 2.0);
    export(&assembly, OUTPUTS[10]);

    println!();
    println!("Closed humidity/dewpoint reference calibration station:");
    println!("  Footprint:              {STATION_X:.0}mm x {STATION_Y:.0}mm closed tray");
    println!(
        "  Probe references:       {PROBE_NEST_COUNT} RH/dewpoint probe nests with guarded cable saddles"
    );
    println!(
        "  Reference standards:    {CAPSULE_WELL_COUNT} sealed salt/reference capsule wells at {CAPSULE_WELL_D:.0}mm diameter"
    );
    println!(
        "  Moisture handling:      {CATCH_CHANNEL_COUNT} condensation channels, catch tray drain, airflow shield, and logger pockets"
    );
    println!(
        "  Traceability/control:   {BARCODE_LAND_COUNT} barcode lands, {CERTIFICATE_LAND_COUNT} certificate lands, release/hold/reject lanes, {BULKHEAD_PORT_COUNT} bulkhead ports, and {ROBOT_KEEP_OUT_ZONE_COUNT} robot keepout zones"
    );
    println!("  Required features:      {}", REQUIRED_FEATURES.len());
}

fn export(part: &Part, path: &str) {
    part.write_stl(path).unwrap();
    println!("Exported: {path}");
}

fn on_base_z(part_z: f64) -> f64 {
    BASE_Z / 2.0 + part_z / 2.0
}

fn centered_index(index: usize, count: usize, pitch: f64) -> f64 {
    -((count as f64 - 1.0) * pitch) / 2.0 + index as f64 * pitch
}

fn assert_design_constraints() {
    assert_eq!(OUTPUTS.len(), 11);
    assert_eq!(REQUIRED_FEATURES.len(), 10);
    assert_eq!(LANE_COUNT, 3);
    assert_eq!(CAPSULE_WELL_COUNT, 8);
    assert_eq!(DATUM_TARGET_COUNT, 4);
    assert!(front_robot_approach_clearance() >= FRONT_ROBOT_APPROACH_CLEARANCE);
    assert!(rear_service_sweep_clearance() >= SERVICE_SWEEP_CLEARANCE);
    assert!(catch_tray_capacity_ml() > reference_capsule_spill_volume_ml());

    for (name, pos, width, depth) in module_specs() {
        assert!(
            fits_inside_rim(pos, width, depth),
            "{name} exceeds base tray"
        );
    }
}

fn module_specs() -> [(&'static str, (f64, f64), f64, f64); 8] {
    [
        ("probe_nest_plate", PROBE_POS, PROBE_NEST_X, PROBE_NEST_Y),
        (
            "reference_capsule_well_block",
            CAPSULE_POS,
            CAPSULE_BLOCK_X,
            CAPSULE_BLOCK_Y,
        ),
        (
            "condensation_catch_tray",
            CATCH_POS,
            CATCH_TRAY_X,
            CATCH_TRAY_Y,
        ),
        (
            "temperature_logger_pocket",
            LOGGER_POS,
            LOGGER_BLOCK_X,
            LOGGER_BLOCK_Y,
        ),
        (
            "airflow_shield",
            AIRFLOW_POS,
            AIRFLOW_SHIELD_X,
            AIRFLOW_SHIELD_Y,
        ),
        (
            "barcode_certificate_lands",
            TRACE_POS,
            TRACE_PLATE_X,
            TRACE_PLATE_Y,
        ),
        (
            "release_hold_reject_lanes",
            LANE_POS,
            LANE_PLATE_X,
            LANE_PLATE_Y,
        ),
        ("service_bulkhead", BULKHEAD_POS, BULKHEAD_X, BULKHEAD_Y),
    ]
}

fn fits_inside_rim(pos: (f64, f64), width: f64, depth: f64) -> bool {
    pos.0.abs() + width / 2.0 <= STATION_X / 2.0 - RIM_W - 8.0
        && pos.1.abs() + depth / 2.0 <= STATION_Y / 2.0 - RIM_W - 8.0
}

fn front_robot_approach_clearance() -> f64 {
    STATION_Y / 2.0 - (LANE_POS.1.abs() + LANE_PLATE_Y / 2.0)
}

fn rear_service_sweep_clearance() -> f64 {
    STATION_Y / 2.0 - (BULKHEAD_POS.1 + BULKHEAD_Y / 2.0)
}

fn catch_tray_capacity_ml() -> f64 {
    (CATCH_TRAY_X - 72.0) * (CATCH_TRAY_Y - 54.0) * CATCH_BASIN_DEPTH / 1000.0
}

fn reference_capsule_spill_volume_ml() -> f64 {
    CAPSULE_WELL_COUNT as f64 * 12.0
}

fn base_tray() -> Part {
    let deck = centered_cube(
        "humidity_dewpoint_station_base_deck",
        STATION_X,
        STATION_Y,
        BASE_Z,
    );
    let basin = centered_cube(
        "humidity_dewpoint_station_secondary_spill_basin_cut",
        STATION_X - 96.0,
        STATION_Y - 92.0,
        7.0,
    )
    .translate(0.0, -6.0, BASE_Z / 2.0 - 3.2);
    let condensate_drain = centered_cylinder(
        "humidity_dewpoint_station_front_condensate_drain_bore",
        10.0 / 2.0,
        46.0,
        32,
    )
    .rotate(90.0, 0.0, 0.0)
    .translate(STATION_X / 2.0 - 82.0, -STATION_Y / 2.0 - 1.0, 0.0);

    deck - basin - condensate_drain - tray_insert_sockets() - mounting_slots() - datum_pin_holes()
        + tray_rims()
        + zone_dividers()
        + station_datum_targets()
        + base_flow_witness_ribs()
}

fn tray_insert_sockets() -> Part {
    let mut sockets = Part::empty("humidity_dewpoint_station_insert_sockets");
    for (name, pos, width, depth) in module_specs() {
        sockets = sockets
            + centered_cube(
                format!("humidity_dewpoint_station_{name}_locator_socket"),
                width + 7.0,
                depth + 7.0,
                SOCKET_DEPTH + 0.6,
            )
            .translate(pos.0, pos.1, BASE_Z / 2.0 - SOCKET_DEPTH / 2.0 + 0.3);
    }
    sockets
}

fn mounting_slots() -> Part {
    let mut slots = Part::empty("humidity_dewpoint_station_mounting_slots");
    for (i, (x, y)) in mount_slot_positions().iter().enumerate() {
        slots = slots
            + centered_cylinder(
                format!("humidity_dewpoint_station_m6_clearance_{i}"),
                6.8 / 2.0,
                BASE_Z + 4.0,
                24,
            )
            .translate(*x, *y, 0.0)
            + centered_cube(
                format!("humidity_dewpoint_station_m6_service_slot_{i}"),
                26.0,
                7.0,
                BASE_Z + 4.0,
            )
            .translate(*x, *y, 0.0);
    }
    slots
}

fn mount_slot_positions() -> [(f64, f64); MOUNT_SLOT_COUNT] {
    [
        (-(STATION_X / 2.0 - 58.0), -(STATION_Y / 2.0 - 54.0)),
        (STATION_X / 2.0 - 58.0, -(STATION_Y / 2.0 - 54.0)),
        (-(STATION_X / 2.0 - 58.0), STATION_Y / 2.0 - 54.0),
        (STATION_X / 2.0 - 58.0, STATION_Y / 2.0 - 54.0),
        (0.0, STATION_Y / 2.0 - 54.0),
        (0.0, -(STATION_Y / 2.0 - 54.0)),
    ]
}

fn datum_pin_holes() -> Part {
    let mut holes = Part::empty("humidity_dewpoint_station_datum_pin_holes");
    for (i, (x, y)) in [
        (-392.0, 250.0),
        (392.0, 250.0),
        (-392.0, -252.0),
        (392.0, -252.0),
    ]
    .iter()
    .enumerate()
    {
        holes = holes
            + centered_cylinder(
                format!("humidity_dewpoint_station_datum_pin_hole_{i}"),
                5.0 / 2.0,
                BASE_Z + 4.0,
                24,
            )
            .translate(*x, *y, 0.0);
    }
    holes
}

fn tray_rims() -> Part {
    let left = centered_cube(
        "humidity_dewpoint_station_left_high_rim",
        RIM_W,
        STATION_Y,
        RIM_Z,
    )
    .translate(
        -STATION_X / 2.0 + RIM_W / 2.0,
        0.0,
        BASE_Z / 2.0 + RIM_Z / 2.0,
    );
    let right = centered_cube(
        "humidity_dewpoint_station_right_high_rim",
        RIM_W,
        STATION_Y,
        RIM_Z,
    )
    .translate(
        STATION_X / 2.0 - RIM_W / 2.0,
        0.0,
        BASE_Z / 2.0 + RIM_Z / 2.0,
    );
    let rear = centered_cube(
        "humidity_dewpoint_station_rear_service_rim",
        STATION_X,
        RIM_W,
        RIM_Z,
    )
    .translate(
        0.0,
        STATION_Y / 2.0 - RIM_W / 2.0,
        BASE_Z / 2.0 + RIM_Z / 2.0,
    );
    let front_low_lip = centered_cube(
        "humidity_dewpoint_station_front_robot_low_lip",
        STATION_X - 150.0,
        12.0,
        20.0,
    )
    .translate(0.0, -STATION_Y / 2.0 + 20.0, BASE_Z / 2.0 + 10.0);

    left + right + rear + front_low_lip
}

fn zone_dividers() -> Part {
    let rear_row = centered_cube(
        "humidity_dewpoint_station_reference_row_divider",
        STATION_X - 130.0,
        10.0,
        24.0,
    )
    .translate(0.0, 108.0, BASE_Z / 2.0 + 12.0);
    let middle_row = centered_cube(
        "humidity_dewpoint_station_condensation_row_divider",
        STATION_X - 150.0,
        10.0,
        22.0,
    )
    .translate(-20.0, -28.0, BASE_Z / 2.0 + 11.0);
    let front_row = centered_cube(
        "humidity_dewpoint_station_release_row_divider",
        STATION_X - 170.0,
        8.0,
        18.0,
    )
    .translate(0.0, -152.0, BASE_Z / 2.0 + 9.0);
    let standards_divider = centered_cube(
        "humidity_dewpoint_station_probe_capsule_column_divider",
        10.0,
        118.0,
        24.0,
    )
    .translate(-30.0, 190.0, BASE_Z / 2.0 + 12.0);
    let logger_divider = centered_cube(
        "humidity_dewpoint_station_logger_traceability_column_divider",
        10.0,
        246.0,
        22.0,
    )
    .translate(166.0, -94.0, BASE_Z / 2.0 + 11.0);

    rear_row + middle_row + front_row + standards_divider + logger_divider
}

fn station_datum_targets() -> Part {
    let mut targets = Part::empty("humidity_dewpoint_station_robot_datum_targets");
    for (i, (x, y)) in [
        (-382.0, 238.0),
        (382.0, 238.0),
        (-382.0, -236.0),
        (382.0, -236.0),
    ]
    .iter()
    .enumerate()
    {
        targets =
            targets
                + fiducial_disc(&format!("humidity_dewpoint_station_robot_fiducial_{i}"))
                    .translate(*x, *y, BASE_Z / 2.0 + 2.5);
    }
    targets
}

fn base_flow_witness_ribs() -> Part {
    let mut ribs = Part::empty("humidity_dewpoint_station_base_condensation_witness_ribs");
    for (i, y) in [-118.0, -70.0, -22.0, 26.0, 74.0].iter().enumerate() {
        ribs = ribs
            + centered_cube(
                format!("humidity_dewpoint_station_base_witness_rib_{i}"),
                STATION_X - 170.0,
                4.0,
                5.0,
            )
            .translate(0.0, *y, BASE_Z / 2.0 + 2.5);
    }
    ribs
}

fn probe_nest_plate() -> Part {
    let body = centered_cube(
        "humidity_dewpoint_probe_nest_plate_body",
        PROBE_NEST_X,
        PROBE_NEST_Y,
        PROBE_NEST_Z,
    );
    let rear_fence = centered_cube(
        "humidity_dewpoint_probe_nest_rear_cable_fence",
        PROBE_NEST_X,
        14.0,
        PROBE_NEST_Z + 30.0,
    )
    .translate(0.0, PROBE_NEST_Y / 2.0 - 7.0, 15.0);

    let mut nest_cuts = Part::empty("humidity_dewpoint_probe_nest_cuts");
    let mut nose_stops = Part::empty("humidity_dewpoint_probe_nest_nose_stops");
    for i in 0..PROBE_NEST_COUNT {
        let x = centered_index(i, PROBE_NEST_COUNT, PROBE_NEST_PITCH_X);
        let name = probe_nest_name(i);
        let sleeve = centered_cylinder(
            format!("humidity_dewpoint_{name}_probe_sleeve_bore"),
            probe_sleeve_diameter(i) / 2.0,
            PROBE_NEST_Y + 12.0,
            36,
        )
        .rotate(90.0, 0.0, 0.0)
        .translate(x, -4.0, 6.0);
        let top_access = centered_cube(
            format!("humidity_dewpoint_{name}_probe_top_access_slot"),
            20.0,
            PROBE_NEST_Y - 20.0,
            20.0,
        )
        .translate(x, -8.0, PROBE_NEST_Z / 2.0 - 5.0);
        let cable_saddle = centered_cube(
            format!("humidity_dewpoint_{name}_probe_cable_saddle"),
            24.0,
            20.0,
            12.0,
        )
        .translate(x, -PROBE_NEST_Y / 2.0 + 14.0, PROBE_NEST_Z / 2.0 - 3.0);
        nest_cuts = nest_cuts + sleeve + top_access + cable_saddle;

        nose_stops = nose_stops
            + centered_cube(
                format!("humidity_dewpoint_{name}_probe_positive_stop"),
                28.0,
                6.0,
                16.0,
            )
            .translate(x, PROBE_NEST_Y / 2.0 - 24.0, PROBE_NEST_Z / 2.0 + 8.0)
            + centered_cube(
                format!("humidity_dewpoint_{name}_probe_serial_flat"),
                48.0,
                16.0,
                3.0,
            )
            .translate(x, -PROBE_NEST_Y / 2.0 + 40.0, PROBE_NEST_Z / 2.0 + 1.5);
    }

    body + rear_fence - nest_cuts + nose_stops + gripper_fiducials("probe_nest_plate")
}

fn probe_nest_name(index: usize) -> &'static str {
    match index {
        0 => "primary_rh",
        1 => "secondary_rh",
        2 => "chilled_mirror_dewpoint",
        _ => "aspirated_reference_rh",
    }
}

fn probe_sleeve_diameter(index: usize) -> f64 {
    match index {
        0 => 9.0,
        1 => 9.0,
        2 => 14.0,
        _ => 11.0,
    }
}

fn reference_capsule_well_block() -> Part {
    let body = centered_cube(
        "humidity_dewpoint_reference_capsule_well_block_body",
        CAPSULE_BLOCK_X,
        CAPSULE_BLOCK_Y,
        CAPSULE_BLOCK_Z,
    );
    let cap_rail = centered_cube(
        "humidity_dewpoint_reference_capsule_tamper_cap_rail",
        CAPSULE_BLOCK_X - 36.0,
        12.0,
        22.0,
    )
    .translate(
        0.0,
        CAPSULE_BLOCK_Y / 2.0 - 18.0,
        CAPSULE_BLOCK_Z / 2.0 + 11.0,
    );

    let mut well_cuts = Part::empty("humidity_dewpoint_reference_capsule_well_cuts");
    let mut well_lands = Part::empty("humidity_dewpoint_reference_capsule_well_lands");
    for i in 0..CAPSULE_WELL_COUNT {
        let (x, y) = capsule_well_position(i);
        let name = reference_capsule_name(i);
        let well = centered_cylinder(
            format!("humidity_dewpoint_{name}_sealed_capsule_well"),
            CAPSULE_WELL_D / 2.0,
            CAPSULE_WELL_DEPTH + 1.0,
            48,
        )
        .translate(x, y, CAPSULE_BLOCK_Z / 2.0 - CAPSULE_WELL_DEPTH / 2.0 + 0.5);
        let key_flat = centered_cube(
            format!("humidity_dewpoint_{name}_capsule_key_flat"),
            16.0,
            8.0,
            CAPSULE_WELL_DEPTH + 2.0,
        )
        .translate(
            x,
            y - CAPSULE_WELL_D / 2.0 + 4.0,
            CAPSULE_BLOCK_Z / 2.0 - CAPSULE_WELL_DEPTH / 2.0 + 0.5,
        );
        well_cuts = well_cuts + well + key_flat;

        let outer_ring = centered_cylinder(
            format!("humidity_dewpoint_{name}_o_ring_land_outer"),
            CAPSULE_WELL_D / 2.0 + 5.0,
            5.0,
            48,
        )
        .translate(x, y, CAPSULE_BLOCK_Z / 2.0 + 2.5);
        let inner_ring = centered_cylinder(
            format!("humidity_dewpoint_{name}_o_ring_land_inner"),
            CAPSULE_WELL_D / 2.0 + 1.4,
            6.0,
            48,
        )
        .translate(x, y, CAPSULE_BLOCK_Z / 2.0 + 2.5);
        let label_tab = centered_cube(
            format!("humidity_dewpoint_{name}_reference_value_tab"),
            46.0,
            12.0,
            3.0,
        )
        .translate(
            x,
            y + CAPSULE_WELL_D / 2.0 + 11.0,
            CAPSULE_BLOCK_Z / 2.0 + 1.5,
        );
        well_lands = well_lands + (outer_ring - inner_ring) + label_tab;
    }

    body - well_cuts + well_lands + cap_rail + gripper_fiducials("capsule_well_block")
}

fn capsule_well_position(index: usize) -> (f64, f64) {
    let col = index % 4;
    let row = index / 4;
    (
        centered_index(col, 4, CAPSULE_WELL_PITCH_X),
        centered_index(row, 2, CAPSULE_WELL_PITCH_Y),
    )
}

fn reference_capsule_name(index: usize) -> &'static str {
    match index {
        0 => "lithium_chloride_11rh",
        1 => "magnesium_chloride_33rh",
        2 => "sodium_chloride_75rh",
        3 => "potassium_sulfate_97rh",
        4 => "dry_reference_capsule",
        5 => "midpoint_reference_capsule",
        6 => "dewpoint_mirror_reference",
        _ => "spent_capsule_witness",
    }
}

