fn gripper_fiducials(prefix: &str) -> Part {
    let left = fiducial_disc(&format!("humidity_dewpoint_{prefix}_left_gripper_fiducial"))
        .translate(-34.0, 0.0, 4.0);
    let right = fiducial_disc(&format!(
        "humidity_dewpoint_{prefix}_right_gripper_fiducial"
    ))
    .translate(34.0, 0.0, 4.0);
    left + right
}

fn fiducial_disc(name: &str) -> Part {
    let disc = centered_cylinder(format!("{name}_outer_disc"), 11.0, 5.0, 36);
    let center = centered_cylinder(format!("{name}_center_dot"), 2.2, 6.0, 24);
    let cross_x = centered_cube(format!("{name}_cross_x"), 18.0, 2.4, 6.0);
    let cross_y = centered_cube(format!("{name}_cross_y"), 2.4, 18.0, 6.0);
    disc - center - cross_x - cross_y
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn output_names_are_stable_and_unique() {
        let unique: HashSet<&str> = OUTPUTS.iter().copied().collect();
        assert_eq!(unique.len(), OUTPUTS.len());
        assert!(OUTPUTS.iter().all(|path| path
            .starts_with("output/closed_humidity_dewpoint_reference_calibration_station_")));
        assert!(OUTPUTS.iter().all(|path| path.ends_with(".stl")));
    }

    #[test]
    fn requested_feature_groups_are_present() {
        for feature in [
            "rh_dewpoint_probe_nests",
            "sealed_salt_solution_reference_capsule_wells",
            "condensation_catch_tray",
            "temperature_logger_pocket",
            "airflow_shield",
            "barcode_certificate_lands",
            "release_hold_reject_lanes",
            "robot_keepouts",
            "service_bulkhead",
        ] {
            assert!(REQUIRED_FEATURES.contains(&feature));
        }
    }

    #[test]
    fn modules_fit_inside_tray_rim() {
        for (name, pos, width, depth) in module_specs() {
            assert!(fits_inside_rim(pos, width, depth), "{name} does not fit");
        }
    }

    #[test]
    fn full_design_constraints_pass() {
        assert_design_constraints();
    }

    #[test]
    fn reference_wells_and_lanes_match_station_plan() {
        assert_eq!(CAPSULE_WELL_COUNT, 8);
        assert_eq!(PROBE_NEST_COUNT, 4);
        assert_eq!(LANE_COUNT, 3);
        assert_eq!(LOGGER_POCKET_COUNT, 2);
        assert_eq!(ROBOT_KEEP_OUT_ZONE_COUNT, 4);
    }

    #[test]
    fn tray_capacity_exceeds_reference_capsule_spill_assumption() {
        assert!(catch_tray_capacity_ml() > reference_capsule_spill_volume_ml());
    }
}
